begin;
update public.ta_lessons set material=jsonb_set(material,'{curiosity}',to_jsonb('Dwie ściany o niemal takim samym drewnianym szkielecie mogą kryć zupełnie inne wypełnienie: cegłę, glinę lub materiał roślinny. Dlatego podczas renowacji nazwy „mur pruski” i „szachulec” nie wystarczą do wyboru sposobu naprawy. Najpierw sprawdza się przekrój, stan podwaliny, słupków, oczepu oraz rzeczywisty materiał wypełnienia — które nie zastępuje automatycznie elementów nośnych.'::text),true)||jsonb_build_object('curiosity_edit','2026-11-17-editorial-first-lesson'),updated_at=now() where course_slug='ciesla-przygotowanie-czeladnicze' and lesson_no=0 and material->>'source_backfill_revision'='2026-11-17-source-grounded-v1';
update public.ta_lessons set material=jsonb_set(material,'{curiosity}',to_jsonb('Roznoszenie posiłków może wyglądać identycznie podczas formalnego wolontariatu i sąsiedzkiej pomocy, lecz organizacja oraz odpowiedzialność mogą być odmienne. Sama nazwa „wolontariusz” nie zamienia zwykłej pracy przy komercyjnych zamówieniach firmy w świadczenie na rzecz uprawnionego podmiotu. Warto zawsze ustalić dla kogo działasz, jaki jest zakres roli, kto koordynuje i kiedy trzeba odmówić nieuzgodnionego zadania.'::text),true)||jsonb_build_object('curiosity_edit','2026-11-17-editorial-first-lesson'),updated_at=now() where course_slug='zaufany-wolontariusz' and lesson_no=0 and material->>'source_backfill_revision'='2026-11-17-source-grounded-v1';
commit;
select course_slug,lesson_no,material->>'curiosity' curiosity from public.ta_lessons where lesson_no=0 and course_slug in ('ciesla-przygotowanie-czeladnicze','zaufany-wolontariusz') order by course_slug;